const url = 'https://federation.ccdi.cancer.gov/api/v1/sample-diagnosis?search=leukemia&library_strategy=RNA-Seq&page=1&per_page=10';
try {
  const res = await fetch(url, { headers: { accept: 'application/json' } });
  const text = await res.text();
  nodeRepl.write(JSON.stringify({ ok: res.ok, status: res.status, statusText: res.statusText, headers: Object.fromEntries(res.headers.entries()), bodyStart: text.slice(0, 20000) }, null, 2));
} catch (e) {
  nodeRepl.write(JSON.stringify({ ok: false, error: String(e), name: e?.name, cause: String(e?.cause || '') }, null, 2));
}

